window.DEVSHELF_REFERENCE_TOPICS = [{"lang":"html","id":"html-document","title":"HTML: структура документа","summary":"Каркас HTML-файла: тип документа, корневой элемент, заголовок и содержимое.","code":"<!doctype html>\n<html lang=\"ru\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Моя страница</title>\n</head>\n<body>\n  <h1>Привет!</h1>\n</body>\n</html>","example":"<main>\n  <h1>План на сегодня</h1>\n  <p>Изучить структуру HTML.</p>\n</main>","points":["<!doctype html> включает современный режим отображения.","<html lang> задаёт язык содержимого страницы.","<head> хранит метаданные, а <body> — видимое содержимое."],"tags":["HTML","doctype","html","head","body","структура"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML","search":true},{"lang":"html","id":"html-metadata","title":"HTML: метаданные страницы","summary":"Настрой кодировку, заголовок вкладки, описание и адаптивность.","code":"<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"description\" content=\"Короткое описание страницы\">\n  <title>Название страницы</title>\n</head>","example":"<meta name=\"theme-color\" content=\"#10151f\">","points":["Кодировку UTF-8 указывай в начале head.","title отображается в заголовке вкладки и результатах поиска.","description — краткое описание страницы; оно не заменяет видимый контент."],"tags":["HTML","meta","title","description","viewport","метаданные"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Reference/Elements/meta","search":true},{"lang":"html","id":"html-semantic","title":"HTML: семантические области","summary":"Используй теги, которые описывают назначение частей страницы.","code":"<header>Шапка сайта</header>\n<nav aria-label=\"Основная навигация\">...</nav>\n<main>\n  <article>\n    <h1>Заголовок статьи</h1>\n    <section><h2>Раздел</h2></section>\n  </article>\n</main>\n<footer>Подвал</footer>","example":"<main>\n  <h1>Каталог книг</h1>\n  <section aria-labelledby=\"popular\">\n    <h2 id=\"popular\">Популярное</h2>\n  </section>\n</main>","points":["header и footer могут относиться ко всей странице или отдельной статье.","На странице обычно один основной main.","section группирует тему, article — самостоятельный материал; nav — важные навигационные ссылки."],"tags":["HTML","header","nav","main","article","section","footer","семантика","структура"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Learn_web_development/Core/Structuring_content","search":true},{"lang":"html","id":"html-text","title":"HTML: текст и заголовки","summary":"Размечай абзацы, цитаты, выделения и иерархию заголовков.","code":"<h1>Тема страницы</h1>\n<h2>Раздел</h2>\n<p>Обычный абзац с <strong>важной</strong> частью.</p>\n<blockquote>\n  <p>Цитата из отдельного источника.</p>\n</blockquote>","example":"<p>Название книги: <cite>Мастер и Маргарита</cite>.</p>\n<p>Формула: H<sub>2</sub>O; степень: x<sup>2</sup>.</p>","points":["Уровень заголовка выбирай по структуре, а не по размеру.","strong сообщает о важности, em — об ударении; оформление задаёт CSS.","Для цитаты используй blockquote, для короткой цитаты — q."],"tags":["HTML","h1","h2","p","strong","em","blockquote","текст","заголовки"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Learn_web_development/Core/Structuring_content/Headings_and_paragraphs","search":true},{"lang":"html","id":"html-links","title":"HTML: ссылки и адреса","summary":"Создавай переходы на страницы, файлы, разделы, email и телефон.","code":"<a href=\"/about.html\">О нас</a>\n<a href=\"#contacts\">Контакты</a>\n<a href=\"mailto:hello@example.com\">Написать</a>","example":"<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener noreferrer\">\n  Открыть сайт в новой вкладке\n</a>","points":["href содержит адрес назначения.","Для открытия новой вкладки добавляй rel=\"noopener noreferrer\".","Текст ссылки должен объяснять, куда она ведёт; для действия используй button."],"tags":["HTML","a","href","ссылка","ссылки","target","rel"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Reference/Elements/a","search":true},{"lang":"html","id":"html-images","title":"HTML: изображения","summary":"Добавляй изображения с альтернативным текстом и размерами.","code":"<img src=\"photo.jpg\" alt=\"Кот спит на подоконнике\"\n     width=\"640\" height=\"480\">","example":"<figure>\n  <img src=\"chart.png\" alt=\"Продажи росли с января по март\">\n  <figcaption>Продажи за первый квартал</figcaption>\n</figure>","points":["alt описывает смысл изображения; декоративному изображению подходит пустой alt=\"\".","Указывай width и height, чтобы зарезервировать место до загрузки.","Для подписи используй figure и figcaption."],"tags":["HTML","img","alt","figure","figcaption","изображение","картинки"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Reference/Elements/img","search":true},{"lang":"html","id":"html-lists","title":"HTML: списки","summary":"Выбирай маркированный, нумерованный или список терминов.","code":"<ul>\n  <li>HTML</li>\n  <li>CSS</li>\n</ul>\n<ol>\n  <li>Открой редактор</li>\n  <li>Сохрани файл</li>\n</ol>","example":"<dl>\n  <dt>DOM</dt>\n  <dd>Объектная модель документа.</dd>\n</dl>","points":["ul — порядок пунктов не важен; ol — последовательность имеет значение.","Каждый пункт списка помещай в li.","dl, dt и dd подходят для терминов и описаний."],"tags":["HTML","ul","ol","li","dl","список","списки"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Learn_web_development/Core/Structuring_content/Lists","search":true},{"lang":"html","id":"html-tables","title":"HTML: таблицы данных","summary":"Представляй табличные данные с заголовками столбцов и строк.","code":"<table>\n  <caption>Расписание</caption>\n  <thead><tr><th scope=\"col\">День</th><th scope=\"col\">Тема</th></tr></thead>\n  <tbody><tr><th scope=\"row\">Пн</th><td>HTML</td></tr></tbody>\n</table>","example":"<td colspan=\"2\">Объединённые столбцы</td>","points":["Таблица подходит для отношений строк и столбцов, не для общей раскладки страницы.","caption задаёт название таблицы.","Связывай th с данными через scope; большие таблицы дели на thead и tbody."],"tags":["HTML","table","tr","td","th","caption","таблица"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Reference/Elements/table","search":true},{"lang":"html","id":"html-forms","title":"HTML: формы и отправка","summary":"Собирай данные через form, label, input и кнопку отправки.","code":"<form action=\"/search\" method=\"get\">\n  <label for=\"query\">Поиск</label>\n  <input id=\"query\" name=\"q\" type=\"search\" required>\n  <button type=\"submit\">Найти</button>\n</form>","example":"<label for=\"email\">Почта</label>\n<input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\">","points":["label связывай с полем через for и id.","name — ключ, под которым значение попадёт в отправляемые данные.","Браузерная валидация помогает пользователю, но сервер всё равно проверяет данные."],"tags":["HTML","form","label","input","submit","форма","формы"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Learn_web_development/Extensions/Forms","search":true},{"lang":"html","id":"html-input-types","title":"HTML: типы полей ввода","summary":"Подбирай input type под ожидаемые данные.","code":"<input type=\"text\" name=\"name\">\n<input type=\"email\" name=\"email\">\n<input type=\"number\" name=\"age\" min=\"0\">\n<input type=\"date\" name=\"date\">\n<input type=\"checkbox\" name=\"agree\" required>","example":"<fieldset>\n  <legend>Способ связи</legend>\n  <label><input type=\"radio\" name=\"contact\" value=\"email\"> Почта</label>\n  <label><input type=\"radio\" name=\"contact\" value=\"phone\"> Телефон</label>\n</fieldset>","points":["Тип поля включает подходящую клавиатуру и базовую проверку.","Для группы radio у всех вариантов одно имя name.","Используй required, min, max и pattern как подсказки; перепроверяй на сервере."],"tags":["HTML","input","email","number","date","checkbox","radio","поле ввода"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Reference/Elements/input","search":true},{"lang":"html","id":"html-buttons","title":"HTML: кнопки и действия","summary":"Различай отправку формы и обычное действие на странице.","code":"<button type=\"button\">Открыть меню</button>\n<button type=\"submit\">Отправить форму</button>","example":"<button type=\"button\" aria-expanded=\"false\" aria-controls=\"details\">\n  Показать подробности\n</button>","points":["Внутри формы button по умолчанию может отправлять форму — задавай type явно.","type=submit отправляет форму, type=reset сбрасывает значения.","Имя кнопки должно описывать действие; для иконки добавляй доступное название."],"tags":["HTML","button","submit","reset","кнопка","кнопки"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Reference/Elements/button","search":true},{"lang":"html","id":"html-audio-video","title":"HTML: аудио и видео","summary":"Встраивай медиа с запасными форматами и доступными элементами управления.","code":"<video controls width=\"640\" poster=\"cover.jpg\">\n  <source src=\"movie.webm\" type=\"video/webm\">\n  <source src=\"movie.mp4\" type=\"video/mp4\">\n  <track src=\"captions.vtt\" kind=\"captions\" srclang=\"ru\" label=\"Русские субтитры\">\n</video>","example":"<audio controls>\n  <source src=\"podcast.mp3\" type=\"audio/mpeg\">\n  Ваш браузер не поддерживает аудио.\n</audio>","points":["controls показывает встроенные кнопки управления.","source позволяет предложить несколько форматов.","Для речи добавляй субтитры или текстовую расшифровку."],"tags":["HTML","video","audio","source","track","медиа","видео","аудио"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Reference/Elements/video","search":true},{"lang":"html","id":"html-details","title":"HTML: раскрывающийся блок","summary":"Создавай нативный блок, который посетитель может раскрыть.","code":"<details>\n  <summary>Как изменить пароль?</summary>\n  <p>Открой настройки профиля и выбери новый пароль.</p>\n</details>","example":"<details open>\n  <summary>Открытый по умолчанию раздел</summary>\n  <p>Атрибут open показывает содержимое сразу.</p>\n</details>","points":["summary должен быть первым дочерним элементом details.","Атрибут open управляет начальным состоянием.","Для сложной логики используй кнопку и состояние в JavaScript."],"tags":["HTML","details","summary","аккордеон","раскрывающийся блок"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Reference/Elements/details","search":true},{"lang":"html","id":"html-data-attributes","title":"HTML: data-* атрибуты","summary":"Передавай пользовательские данные элементам для JavaScript.","code":"<button data-product-id=\"42\">В корзину</button>","example":"const button = document.querySelector('button');\nconsole.log(button.dataset.productId);","points":["Имена data-* доступны через элемент.dataset.","В JavaScript camelCase соответствует имени после data-.","Не храни в data-* секреты и не подставляй непроверенные значения в HTML."],"tags":["HTML","data","dataset","атрибуты","JavaScript"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Global_attributes/data-*","search":true},{"lang":"html","id":"html-accessibility","title":"HTML: доступность интерфейса","summary":"Строй разметку так, чтобы сайтом можно было пользоваться с клавиатуры и скринридером.","code":"<label for=\"city\">Город</label>\n<select id=\"city\" name=\"city\">\n  <option value=\"msk\">Москва</option>\n</select>\n<button type=\"button\" aria-label=\"Закрыть\">×</button>","example":"<main>\n  <h1>Настройки</h1>\n  <a href=\"#content\">Перейти к содержимому</a>\n</main>","points":["Используй семантические элементы и правильный порядок заголовков.","Каждому полю ввода нужна подпись.","Не передавай значение только цветом; сохраняй видимый фокус клавиатуры."],"tags":["HTML","доступность","aria","скринридер","клавиатура","a11y"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Learn_web_development/Core/Accessibility","search":true},{"lang":"html","id":"html-scripts","title":"HTML: подключение JavaScript","summary":"Подключай внешний скрипт так, чтобы разметка не блокировала загрузку страницы.","code":"<script src=\"app.js\" defer></script>","example":"<script type=\"module\" src=\"src/main.js\"></script>","points":["defer запускает обычный скрипт после разбора HTML и сохраняет порядок.","Модули используют import и export и работают в строгом режиме.","Не вставляй исполняемые данные пользователя в содержимое script."],"tags":["HTML","script","defer","module","подключить JavaScript"],"url":"https://developer.mozilla.org/ru/docs/Web/HTML/Reference/Elements/script","search":true},{"lang":"css","id":"css-selectors","title":"CSS: селекторы","summary":"Выбирай элементы по тегу, классу, атрибуту и состоянию.","code":"p { line-height: 1.6; }\n.card { padding: 1rem; }\n#main { max-width: 70rem; }\ninput[type=\"email\"] { border-color: teal; }\na:hover { text-decoration: underline; }","example":".card > h2 { margin-top: 0; }\nnav a[aria-current=\"page\"] { color: limegreen; }","points":["Класс подходит для повторного применения; ID должен быть уникальным.","Комбинаторы связывают элементы по структуре.","Псевдоклассы описывают состояние, например :hover, :focus-visible и :checked."],"tags":["CSS","селектор","класс","id","псевдокласс","атрибут"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/Selectors","search":true},{"lang":"css","id":"css-cascade","title":"CSS: каскад и специфичность","summary":"Понимай, почему одно правило переопределяет другое.","code":".card { color: #243044; }\narticle.card { color: #152030; }\n#featured { color: #102010; }","example":"/* Позднее правило той же специфичности победит раннее. */\n.button { color: white; }\n.button { color: navy; }","points":["Учитывай происхождение, важность, специфичность и порядок правил.","ID обычно специфичнее класса, класс — селектора тега.","Не злоупотребляй !important: он затрудняет дальнейшие изменения."],"tags":["CSS","cascade","каскад","специфичность","important","наследование"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/Cascade","search":true},{"lang":"css","id":"css-box-model","title":"CSS: блочная модель","summary":"Рассчитывай размеры через содержимое, внутренний отступ, рамку и внешний отступ.","code":".card {\n  width: 320px;\n  padding: 20px;\n  border: 1px solid #ccd;\n  margin: 16px;\n  box-sizing: border-box;\n}","example":"*, *::before, *::after { box-sizing: border-box; }","points":["При content-box padding и border добавляются поверх width.","border-box включает padding и border в заданную ширину.","margin — внешнее расстояние; padding — внутреннее."],"tags":["CSS","box model","width","height","padding","margin","border","блочная модель"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/CSS_box_model","search":true},{"lang":"css","id":"css-units","title":"CSS: единицы измерения","summary":"Сочетай относительные и абсолютные единицы по задаче.","code":":root { font-size: 16px; }\nh1 { font-size: 2rem; }\n.card { width: min(100%, 60rem); padding: 1.25em; }\n.hero { min-height: 70vh; }","example":"img { width: 100%; max-width: 40rem; height: auto; }","points":["px удобны для тонких границ и точных деталей.","rem считается от корневого размера шрифта; em — от размера текущего контекста.","%, vw, vh и современные динамические единицы помогают строить адаптивные размеры."],"tags":["CSS","px","rem","em","vw","vh","единицы"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/CSS_Values_and_Units","search":true},{"lang":"css","id":"css-colors","title":"CSS: цвет и прозрачность","summary":"Задавай цвета в HEX, RGB, HSL и через системные переменные.","code":":root {\n  --accent: hsl(100 78% 70%);\n  --text: #e9eef7;\n}\n.button { color: rgb(12 18 28); background: var(--accent); }","example":".overlay { background: rgb(0 0 0 / 55%); }","points":["HEX подходит для компактных фиксированных значений.","HSL удобно менять по тону, насыщенности и светлоте.","Проверяй контраст текста и фона; прозрачность влияет на итоговый цвет."],"tags":["CSS","color","цвет","hex","rgb","hsl","opacity"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/color_value","search":true},{"lang":"css","id":"css-typography","title":"CSS: текст и шрифты","summary":"Настраивай семейство шрифта, размер, ширину строки и межстрочное расстояние.","code":"body {\n  font-family: system-ui, sans-serif;\n  font-size: 1rem;\n  line-height: 1.6;\n}\nh1 { font-weight: 800; letter-spacing: -0.03em; }","example":"p { max-width: 68ch; }","points":["Указывай резервные семейства после основного шрифта.","ch помогает ограничить удобную ширину текстовой строки.","Не отключай масштабирование и не делай основной текст слишком мелким."],"tags":["CSS","font-family","font-size","line-height","шрифт","типографика"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/font","search":true},{"lang":"css","id":"css-display","title":"CSS: display и поток","summary":"Определи, участвует ли элемент в блочном, строчном или гибком потоке.","code":".hidden { display: none; }\n.inline { display: inline; }\n.row { display: flex; }\n.grid { display: grid; }","example":".badge { display: inline-flex; align-items: center; gap: .4rem; }","points":["block занимает доступную ширину строки и начинается с новой строки.","inline остаётся в текстовом потоке; размеры ведут себя иначе.","none убирает элемент из раскладки; visibility:hidden сохраняет место."],"tags":["CSS","display","block","inline","none","поток"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/display","search":true},{"lang":"css","id":"css-flexbox","title":"CSS: Flexbox","summary":"Распределяй элементы вдоль одной основной оси.","code":".toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1rem;\n  flex-wrap: wrap;\n}","example":".actions { display: flex; gap: .75rem; }","points":["flex-direction меняет направление основной оси.","justify-content распределяет элементы вдоль основной оси.","align-items выравнивает по поперечной оси; gap задаёт промежуток."],"tags":["CSS","flex","flexbox","justify-content","align-items","gap","раскладка"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/CSS_flexible_box_layout","search":true},{"lang":"css","id":"css-grid","title":"CSS: CSS Grid","summary":"Строй двухмерные сетки строк и колонок.","code":".cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));\n  gap: 1rem;\n}","example":".layout { display: grid; grid-template-columns: 16rem 1fr; }","points":["Grid удобен, когда нужно управлять одновременно строками и столбцами.","minmax задаёт диапазон размера дорожки.","auto-fit и auto-fill помогают строить адаптивные колонки."],"tags":["CSS","grid","grid-template-columns","minmax","сетка"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/CSS_grid_layout","search":true},{"lang":"css","id":"css-position","title":"CSS: position и слои","summary":"Управляй размещением элемента относительно потока и якоря.","code":".container { position: relative; }\n.badge {\n  position: absolute;\n  inset-block-start: .5rem;\n  inset-inline-end: .5rem;\n}\n.sticky { position: sticky; top: 0; }","example":"dialog[open] { position: fixed; inset: 0; margin: auto; }","points":["static — обычное положение; relative сохраняет место и создаёт якорь.","absolute позиционируется относительно ближайшего позиционированного предка.","fixed закрепляется относительно окна; sticky прилипает в пределах своего контейнера."],"tags":["CSS","position","absolute","relative","fixed","sticky","z-index"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/position","search":true},{"lang":"css","id":"css-responsive","title":"CSS: адаптивная вёрстка","summary":"Подстраивай интерфейс под доступную ширину и предпочтения пользователя.","code":".cards { display: grid; grid-template-columns: repeat(3, 1fr); }\n@media (max-width: 760px) {\n  .cards { grid-template-columns: 1fr; }\n}","example":"@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; }\n}","points":["Начинай с гибких размеров и ограничений max-width.","Медиазапросы добавляй там, где ломается содержимое, а не под каждую модель устройства.","Уважай prefers-reduced-motion и ориентацию экрана."],"tags":["CSS","media query","адаптивность","responsive","медиазапрос"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/CSS_media_queries","search":true},{"lang":"css","id":"css-custom-properties","title":"CSS: переменные и темы","summary":"Храни повторяющиеся значения в пользовательских свойствах.","code":":root {\n  --surface: #121b29;\n  --text: #edf3fc;\n  --accent: #a6f078;\n}\n.card { color: var(--text); background: var(--surface); }","example":"body.light {\n  --surface: #fff;\n  --text: #172033;\n}","points":["Свойства с префиксом -- наследуются по обычным правилам CSS.","var() может принимать запасное значение: var(--accent, green).","Переменные удобно переопределять на контейнере темы."],"tags":["CSS","--custom-property","var","переменные","тема"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/CSS_cascading_variables/Using_CSS_custom_properties","search":true},{"lang":"css","id":"css-pseudo","title":"CSS: псевдоклассы и псевдоэлементы","summary":"Стилизуй состояние и части элемента без лишней разметки.","code":"a:hover { color: #9b4c20; }\nbutton:focus-visible { outline: 3px solid orange; }\nli::marker { color: green; }\n.card::before { content: \"✦\"; }","example":"input:invalid { border-color: crimson; }","points":["Псевдоклассы начинаются с :, например :hover и :focus-visible.","Псевдоэлементы начинаются с ::, например ::before и ::marker.","Не полагайся только на hover: обеспечь управление клавиатурой."],"tags":["CSS","pseudo-class","pseudo-element","hover","focus-visible","before","after"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/Pseudo-classes","search":true},{"lang":"css","id":"css-transitions","title":"CSS: переходы","summary":"Анимируй изменение свойства при смене состояния.","code":".button {\n  background: #a6f078;\n  transition: background-color 160ms ease, transform 160ms ease;\n}\n.button:hover { transform: translateY(-2px); }","example":"@media (prefers-reduced-motion: reduce) {\n  .button { transition: none; }\n}","points":["Перечисляй конкретные свойства, которые нужно анимировать.","Длительность обычно короткая для отклика управления.","Пользователям с уменьшением движения отключай декоративные переходы."],"tags":["CSS","transition","переход","анимация","hover"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/CSS_transitions","search":true},{"lang":"css","id":"css-animation","title":"CSS: keyframes и анимации","summary":"Определи последовательность кадров и настрой повторение.","code":"@keyframes appear {\n  from { opacity: 0; transform: translateY(8px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n.notice { animation: appear 240ms ease-out both; }","example":"@media (prefers-reduced-motion: reduce) {\n  .notice { animation: none; }\n}","points":["@keyframes задаёт состояния анимации.","animation-duration и timing-function задают время и характер движения.","Не анимируй много тяжёлых свойств одновременно; проверяй производительность."],"tags":["CSS","@keyframes","animation","кадры","анимация"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/CSS_animations","search":true},{"lang":"css","id":"css-overflow","title":"CSS: переполнение и обрезка","summary":"Решай, что делать с содержимым, выходящим за границы блока.","code":".panel {\n  max-height: 20rem;\n  overflow: auto;\n}\n.title {\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}","example":".code { overflow-x: auto; }","points":["visible показывает переполнение; hidden обрезает; auto добавляет прокрутку при необходимости.","Для длинного кода часто нужен overflow-x:auto.","text-overflow:ellipsis требует ограничения размера и управления переносом."],"tags":["CSS","overflow","scroll","ellipsis","переполнение","обрезка"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/overflow","search":true},{"lang":"css","id":"css-borders","title":"CSS: рамки, радиус и тени","summary":"Оформи границы и глубину компонентов.","code":".card {\n  border: 1px solid #2b394d;\n  border-radius: 14px;\n  box-shadow: 0 12px 32px rgb(0 0 0 / 18%);\n}","example":"button { border: 0; border-radius: 999px; }","points":["border задаёт толщину, стиль и цвет рамки.","border-radius скругляет углы; большое значение создаёт капсулу.","Тени используй для иерархии, не заменяй ими реальные границы везде."],"tags":["CSS","border","border-radius","box-shadow","рамка","тень"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/border","search":true},{"lang":"css","id":"css-containment","title":"CSS: размеры и ограничения","summary":"Контролируй минимальные, максимальные и пропорциональные размеры.","code":".content { width: min(100% - 2rem, 72rem); margin-inline: auto; }\n.avatar { width: 3rem; aspect-ratio: 1; border-radius: 50%; }\n.media { max-width: 100%; height: auto; }","example":"h1 { font-size: clamp(2rem, 5vw, 4.5rem); }","points":["min-width и min-height защищают содержимое от слишком малого контейнера.","max-width часто помогает изображениям и строкам текста.","clamp(min, preferred, max) задаёт адаптивный диапазон."],"tags":["CSS","width","height","min-width","max-width","aspect-ratio","clamp"],"url":"https://developer.mozilla.org/ru/docs/Web/CSS/length","search":true},{"lang":"javascript","id":"js-values","title":"JavaScript: значения и типы","summary":"Различай примитивы, объекты, отсутствие значения и проверку типа.","code":"const title = \"DevShelf\";\nconst count = 3;\nconst active = true;\nconst missing = null;\nlet result;\nconsole.log(typeof title, typeof count);","example":"const user = {name: \"Аня\"};\nconsole.log(user.name);","points":["Примитивы включают строки, числа, bigint, boolean, null, undefined и symbol.","Объекты хранят коллекции и имеют ссылочную семантику.","typeof null исторически возвращает \"object\"; проверяй null сравнением."],"tags":["JavaScript","тип","typeof","null","undefined","примитив"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Guide/Data_structures","search":true},{"lang":"javascript","id":"js-operators","title":"JavaScript: операторы и сравнения","summary":"Вычисляй значения и сравнивай их без скрытых преобразований.","code":"const total = price * quantity;\nconst canSubmit = name.trim() !== \"\" && email.includes(\"@\");\nconst same = value === expected;","example":"const label = count === 1 ? \"раз\" : \"раза\";","points":["=== и !== сравнивают без неявного приведения типа.","&&, || и ! работают с логическими условиями.","Оператор ?? выбирает запасное значение только при null или undefined."],"tags":["JavaScript","операторы","сравнение","равенство","условия"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Guide/Expressions_and_operators","search":true},{"lang":"javascript","id":"js-conditionals","title":"JavaScript: условия и ветвления","summary":"Выбирай поведение программы по логическому условию.","code":"if (score >= 90) {\n  console.log(\"Отлично\");\n} else if (score >= 60) {\n  console.log(\"Зачёт\");\n} else {\n  console.log(\"Попробуй ещё раз\");\n}","example":"const message = isOpen ? \"Закрыть\" : \"Открыть\";","points":["if выполняет ветку при истинном условии.","switch подходит для выбора среди нескольких фиксированных вариантов.","Условия пиши явно и избегай глубокой вложенности."],"tags":["JavaScript","if","else","switch","условие","ветвление"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Guide/Control_flow_and_error_handling","search":true},{"lang":"javascript","id":"js-loops","title":"JavaScript: циклы","summary":"Повторяй код для последовательности или пока истинно условие.","code":"for (let i = 0; i < 3; i++) {\n  console.log(i);\n}\nfor (const item of items) {\n  console.log(item);\n}","example":"let attempts = 0;\nwhile (attempts < 3) {\n  attempts += 1;\n}","points":["for удобен, если нужен индекс или известен диапазон.","for...of перебирает значения итерируемых коллекций.","Не меняй условие цикла так, чтобы он стал бесконечным."],"tags":["JavaScript","for","while","for of","цикл","циклы"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Guide/Loops_and_iteration","search":true},{"lang":"javascript","id":"js-objects","title":"JavaScript: объекты","summary":"Объединяй связанные данные в именованные свойства.","code":"const user = {\n  name: \"Аня\",\n  active: true,\n  greet() {\n    return \"Привет, \" + this.name;\n  }\n};\nconsole.log(user.greet());","example":"const {name, active} = user;\nconst copy = {...user, active: false};","points":["Свойства доступны через точку или квадратные скобки.","Деструктуризация извлекает нужные свойства в переменные.","Spread создаёт поверхностную копию; вложенные объекты остаются общими."],"tags":["JavaScript","object","объект","свойства","методы","деструктуризация"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Guide/Working_with_objects","search":true},{"lang":"javascript","id":"js-scope","title":"JavaScript: область видимости","summary":"Понимай, где переменная существует и когда замыкание сохраняет доступ.","code":"const page = \"home\";\nfunction show() {\n  const message = \"Раздел: \" + page;\n  return message;\n}\nconsole.log(show());","example":"for (let i = 0; i < 3; i++) {\n  setTimeout(() => console.log(i), 0);\n}","points":["let и const ограничены блоком; var — функцией или глобальной областью.","Внутренняя функция может читать внешние переменные — это замыкание.","Не создавай случайные глобальные переменные."],"tags":["JavaScript","scope","область видимости","замыкание","closure"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Guide/Closures","search":true},{"lang":"javascript","id":"js-errors","title":"JavaScript: ошибки и исключения","summary":"Обрабатывай ожидаемые сбои и показывай понятное состояние.","code":"try {\n  const data = JSON.parse(text);\n  render(data);\n} catch (error) {\n  console.error(\"Не удалось прочитать данные:\", error.message);\n}","example":"function parseAge(value) {\n  if (!Number.isFinite(value)) {\n    throw new TypeError(\"Возраст должен быть числом\");\n  }\n  return value;\n}","points":["throw создаёт исключение и передаёт управление ближайшему catch.","finally выполняется и при успехе, и при ошибке.","Не скрывай ошибку пустым catch; сообщай пользователю безопасно."],"tags":["JavaScript","ошибка","try","catch","throw","исключения"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Guide/Control_flow_and_error_handling","search":true},{"lang":"javascript","id":"js-modules","title":"JavaScript: модули import и export","summary":"Разделяй программу на файлы с явными зависимостями.","code":"// math.js\nexport function sum(a, b) {\n  return a + b;\n}\n// main.js\nimport {sum} from \"./math.js\";\nconsole.log(sum(2, 3));","example":"export default function formatDate(date) {\n  return new Intl.DateTimeFormat(\"ru-RU\").format(date);\n}","points":["Именованный экспорт позволяет импортировать конкретные значения.","У модуля может быть один default export.","В браузере подключай entry-файл с type=\"module\"."],"tags":["JavaScript","import","export","модуль","modules"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Guide/Modules","search":true},{"lang":"javascript","id":"js-dom-create","title":"JavaScript: изменение DOM","summary":"Создавай, находи и обновляй HTML-элементы из JavaScript.","code":"const list = document.querySelector(\"#list\");\nconst item = document.createElement(\"li\");\nitem.textContent = \"Изучить DOM\";\nlist.append(item);","example":"document.querySelector(\".notice\")?.classList.add(\"is-visible\");","points":["createElement создаёт узел; append добавляет его в DOM.","textContent безопасно вставляет обычный текст.","Избегай частого чтения и записи layout-свойств в длинных циклах."],"tags":["JavaScript","DOM","createElement","append","textContent","элемент"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Web/API/Document_Object_Model","search":true},{"lang":"javascript","id":"js-event-delegation","title":"JavaScript: делегирование событий","summary":"Обрабатывай события дочерних элементов одним слушателем на контейнере.","code":"document.querySelector(\"#list\").addEventListener(\"click\", event => {\n  const button = event.target.closest(\"[data-remove]\");\n  if (!button) return;\n  button.closest(\"li\").remove();\n});","example":"form.addEventListener(\"submit\", event => {\n  event.preventDefault();\n  saveForm();\n});","points":["Событие всплывает от дочернего узла к предкам.","closest помогает найти элемент действия рядом с целью клика.","Делегирование удобно для списков, элементы которых добавляются динамически."],"tags":["JavaScript","event","событие","делегирование","closest","всплытие"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Learn_web_development/Core/Scripting/Event_bubbling","search":true},{"lang":"javascript","id":"js-forms","title":"JavaScript: работа с формами","summary":"Считывай значения, проверяй форму и показывай ошибки.","code":"const form = document.querySelector(\"#signup\");\nform.addEventListener(\"submit\", event => {\n  event.preventDefault();\n  const data = new FormData(form);\n  console.log(data.get(\"email\"));\n});","example":"const email = form.elements.email.value.trim();","points":["submit обрабатывает отправку кнопкой или клавишей Enter.","FormData собирает поля по атрибуту name.","Клиентская проверка улучшает удобство, но не заменяет серверную."],"tags":["JavaScript","форма","FormData","submit","валидация","поля"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Web/API/FormData","search":true},{"lang":"javascript","id":"js-storage","title":"JavaScript: localStorage и sessionStorage","summary":"Сохраняй небольшие строковые данные в браузере.","code":"localStorage.setItem(\"theme\", \"dark\");\nconst theme = localStorage.getItem(\"theme\");\nlocalStorage.removeItem(\"theme\");","example":"const favorites = JSON.parse(localStorage.getItem(\"favorites\") || \"[]\");\nlocalStorage.setItem(\"favorites\", JSON.stringify([...favorites, \"nav\"]));","points":["Хранилища синхронны и принимают строки.","Для объектов используй JSON.stringify и JSON.parse.","Не сохраняй секреты, пароли или чувствительные данные."],"tags":["JavaScript","localStorage","sessionStorage","хранилище","избранное"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Web/API/Web_Storage_API","search":true},{"lang":"javascript","id":"js-date","title":"JavaScript: даты и форматирование","summary":"Создавай даты и выводи локализованный текст через Intl.","code":"const now = new Date();\nconst label = new Intl.DateTimeFormat(\"ru-RU\", {\n  dateStyle: \"long\",\n  timeStyle: \"short\"\n}).format(now);","example":"const iso = new Date().toISOString();","points":["Date хранит момент времени в миллисекундах относительно UTC.","Локальный вывод создавай через Intl.DateTimeFormat.","ISO-строку удобно передавать в API, но не обязательно показывать напрямую."],"tags":["JavaScript","Date","дата","время","Intl","форматирование"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Reference/Global_Objects/Date","search":true},{"lang":"javascript","id":"js-map-set","title":"JavaScript: Map и Set","summary":"Используй коллекции для ключей и уникальных значений.","code":"const visits = new Map();\nvisits.set(\"home\", 3);\nconsole.log(visits.get(\"home\"));\nconst uniqueTags = new Set([\"php\", \"js\", \"php\"]);","example":"const seen = new Set(items.map(item => item.id));","points":["Map хранит пары ключ—значение; ключом может быть объект.","Set сохраняет только уникальные значения.","Выбирай обычный объект для записи свойств, Map — для коллекции пар."],"tags":["JavaScript","Map","Set","коллекции","уникальность"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Guide/Keyed_collections","search":true},{"lang":"javascript","id":"js-array-methods","title":"JavaScript: map, filter, reduce","summary":"Преобразуй, отбирай и своди значения массивов.","code":"const names = users.map(user => user.name);\nconst adults = users.filter(user => user.age >= 18);\nconst total = prices.reduce((sum, price) => sum + price, 0);","example":"const match = users.find(user => user.id === selectedId);","points":["map возвращает преобразованный массив той же длины.","filter оставляет элементы, прошедшие условие.","reduce сводит коллекцию к одному значению; для простых задач предпочитай понятные методы."],"tags":["JavaScript","map","filter","reduce","find","массивы"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Reference/Global_Objects/Array","search":true},{"lang":"javascript","id":"js-network-errors","title":"JavaScript: отмена и тайм-аут fetch","summary":"Управляй жизненным циклом сетевого запроса.","code":"const controller = new AbortController();\nconst timeout = setTimeout(() => controller.abort(), 5000);\ntry {\n  const response = await fetch(\"/api/items\", {signal: controller.signal});\n  if (!response.ok) throw new Error(\"HTTP \" + response.status);\n  const items = await response.json();\n} finally {\n  clearTimeout(timeout);\n}","example":"const response = await fetch(\"/api/profile\", {\n  headers: {Accept: \"application/json\"}\n});","points":["AbortController отменяет запрос через сигнал.","fetch отклоняется при сетевой ошибке, но не автоматически при статусе 404.","Проверяй response.ok и корректно показывай состояние загрузки."],"tags":["JavaScript","fetch","AbortController","запрос","ошибка сети","тайм-аут"],"url":"https://developer.mozilla.org/ru/docs/Web/JavaScript/Web/API/Fetch_API/Using_Fetch","search":true},{"lang":"php","id":"array","title":"PHP: массивы","summary":"Индексированные и ассоциативные наборы данных.","code":"$languages = ['PHP', 'JavaScript', 'HTML'];\n$languages[] = 'CSS';\necho $languages[0];","example":"$user = ['name' => 'Анна', 'role' => 'разработчик'];\necho $user['name'];","points":["Индексы индексированного массива начинаются с нуля.","Ассоциативный массив хранит пары ключ => значение.","Массив PHP может содержать смешанные типы и служит базовой коллекцией."],"tags":["PHP","array","массив","массивы","ключ","значение"],"url":"https://www.php.net/manual/ru/language.types.array.php","search":false},{"lang":"php","id":"foreach","title":"PHP: цикл foreach","summary":"Перебирай индексированные и ассоциативные массивы.","code":"$fruits = ['яблоко', 'груша'];\nforeach ($fruits as $fruit) {\n    echo $fruit . PHP_EOL;\n}","example":"foreach ($prices as $product => $price) {\n    echo $product . ': ' . $price . PHP_EOL;\n}","points":["В цикле доступны текущее значение и при необходимости ключ.","Для изменения значения по ссылке нужен префикс &; избегай его без необходимости.","Для числового счётчика часто подходит for."],"tags":["PHP","foreach","цикл","перебор","массив"],"url":"https://www.php.net/manual/ru/control-structures.foreach.php","search":false},{"lang":"php","id":"function","title":"PHP: функции","summary":"Объявляй функции с понятными параметрами, типами и результатом.","code":"function greet(string $name): string\n{\n    return 'Привет, ' . $name . '!';\n}","example":"function total(float $price, int $count = 1): float\n{\n    return $price * $count;\n}","points":["return возвращает значение и завершает выполнение функции.","Типы параметров и возвращаемого значения фиксируют ожидания.","Параметрам можно задавать значения по умолчанию."],"tags":["PHP","function","функция","функции","параметры","return"],"url":"https://www.php.net/manual/ru/language.functions.php","search":false},{"lang":"php","id":"form","title":"PHP: формы и $_GET / $_POST","summary":"Читай данные формы на сервере и безопасно показывай значения.","code":"if ($_SERVER['REQUEST_METHOD'] === 'POST') {\n    $name = trim($_POST['name'] ?? '');\n    echo htmlspecialchars($name, ENT_QUOTES, 'UTF-8');\n}","example":"<form method=\"post\">\n  <label>Имя <input name=\"name\" required></label>\n  <button type=\"submit\">Отправить</button>\n</form>","points":["Поле формы должно иметь атрибут name.","GET передаёт параметры в URL; POST отправляет данные в теле запроса.","Экранируй данные перед выводом в HTML и валидируй их на сервере."],"tags":["PHP","form","форма","GET","POST","$_GET","$_POST"],"url":"https://www.php.net/manual/ru/tutorial.forms.php","search":false},{"lang":"php","id":"pdo","title":"PHP: PDO и подготовленные запросы","summary":"Выполняй параметризованные SQL-запросы через PDO.","code":"$statement = $pdo->prepare(\n    'SELECT id, name FROM users WHERE email = :email'\n);\n$statement->execute(['email' => $email]);\n$user = $statement->fetch();","example":"$pdo = new PDO($dsn, $username, $password, [\n    PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,\n    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,\n]);","points":["Передавай значения отдельно, не вставляй их конкатенацией в SQL.","Выбирай драйвер через строку DSN.","Ошибки запросов обрабатывай исключениями и логируй без раскрытия секретов."],"tags":["PHP","PDO","SQL","база данных","подготовленный запрос"],"url":"https://www.php.net/manual/ru/book.pdo.php","search":false},{"lang":"php","id":"class","title":"PHP: классы и объекты","summary":"Объединяй состояние и операции в классах.","code":"class User\n{\n    public function __construct(public string $name) {}\n\n    public function greet(): string\n    {\n        return 'Привет, ' . $this->name;\n    }\n}","example":"$user = new User('Мир');\necho $user->greet();","points":["new создаёт экземпляр класса.","$this обращается к текущему объекту.","public, protected и private задают видимость свойств и методов."],"tags":["PHP","class","класс","объект","ООП","метод"],"url":"https://www.php.net/manual/ru/language.oop5.php","search":false},{"lang":"php","id":"echo","title":"PHP: echo и вывод","summary":"Выводи текст и безопасно включай значения в HTML.","code":"$name = 'Мир';\necho 'Привет, ' . $name . '!';","example":"$title = 'Моя страница';\n?>\n<h1><?= htmlspecialchars($title, ENT_QUOTES, 'UTF-8') ?></h1>\n<?php","points":["Точка соединяет строки.","Короткая форма <?= ... ?> выводит выражение.","Пользовательские значения экранируй под контекст вывода."],"tags":["PHP","echo","вывод","htmlspecialchars","строки"],"url":"https://www.php.net/manual/ru/function.echo.php","search":false},{"lang":"php","id":"php-syntax","title":"PHP: синтаксис и блоки кода","summary":"Встраивай серверный код между открывающим и закрывающим тегами PHP.","code":"<?php\ndeclare(strict_types=1);\n\n$message = 'Привет!';\necho $message;\n?>","example":"<?php if ($isReady): ?>\n  <p>Готово</p>\n<?php else: ?>\n  <p>Ожидаем</p>\n<?php endif; ?>","points":["PHP исполняется на сервере; браузер получает результат, обычно HTML.","Инструкции обычно заканчиваются точкой с запятой.","В файлах, состоящих только из PHP, закрывающий тег обычно опускают."],"tags":["PHP","синтаксис","теги","<?php","точка с запятой"],"url":"https://www.php.net/manual/ru/language.basic-syntax.php","search":true},{"lang":"php","id":"php-types","title":"PHP: типы и преобразования","summary":"Используй значения корректного типа и контролируй преобразования.","code":"$count = 3;\n$price = 12.50;\n$title = 'Книга';\n$active = true;\n$nothing = null;","example":"function add(int $a, int $b): int\n{\n    return $a + $b;\n}","points":["PHP переменные начинаются с $.","Типы включают int, float, string, bool, array, object, null и другие.","Строгая типизация файла включается declare(strict_types=1); в его начале."],"tags":["PHP","типы","int","string","bool","null","переменные"],"url":"https://www.php.net/manual/ru/language.types.php","search":true},{"lang":"php","id":"php-strings","title":"PHP: строки","summary":"Соединяй, форматируй и безопасно выводи текст.","code":"$first = 'Анна';\n$message = 'Привет, ' . $first . '!';\n$length = mb_strlen($message, 'UTF-8');","example":"$path = \"Документы\\Отчёт.pdf\";","points":["Одинарные кавычки подходят для строк без интерполяции.","Точка соединяет строки.","Для длины и обработки Unicode используй mb_* при доступном расширении."],"tags":["PHP","строка","string","кавычки","конкатенация","mb_strlen"],"url":"https://www.php.net/manual/ru/language.types.string.php","search":true},{"lang":"php","id":"php-conditionals","title":"PHP: условия и match","summary":"Выбирай ветку выполнения по значению и условию.","code":"if ($score >= 60) {\n    echo 'Зачёт';\n} else {\n    echo 'Попробуй ещё раз';\n}","example":"$label = match ($status) {\n    'new' => 'Новый',\n    'paid' => 'Оплачен',\n    default => 'Неизвестно',\n};","points":["if / elseif / else обрабатывают логические условия.","match сравнивает строго и возвращает значение.","Для нескольких независимых проверок избегай чрезмерно вложенных условий."],"tags":["PHP","if","else","match","условие","ветвление"],"url":"https://www.php.net/manual/ru/control-structures.if.php","search":true},{"lang":"php","id":"php-loops","title":"PHP: циклы for и while","summary":"Повторяй блок кода по счётчику или пока условие истинно.","code":"for ($i = 0; $i < 3; $i++) {\n    echo $i . PHP_EOL;\n}","example":"while ($row = $statement->fetch()) {\n    process($row);\n}","points":["for задаёт старт, условие и изменение счётчика.","while проверяет условие перед каждой итерацией.","Для массива чаще используй foreach."],"tags":["PHP","for","while","цикл","циклы"],"url":"https://www.php.net/manual/ru/control-structures.for.php","search":true},{"lang":"php","id":"php-errors","title":"PHP: ошибки и исключения","summary":"Перехватывай ожидаемые исключения, логируй детали безопасно.","code":"try {\n    $user = loadUser($id);\n} catch (NotFoundException $error) {\n    http_response_code(404);\n    echo 'Пользователь не найден';\n}","example":"throw new InvalidArgumentException('Некорректный идентификатор');","points":["Исключение передаёт управление блоку catch.","Наследуй доменные ошибки от подходящего типа исключения.","Посетителю показывай нейтральное сообщение, технические детали храни в журнале."],"tags":["PHP","try","catch","throw","ошибки","исключения"],"url":"https://www.php.net/manual/ru/language.exceptions.php","search":true},{"lang":"php","id":"php-include","title":"PHP: include и require","summary":"Подключай общие файлы и разделяй код на части.","code":"require_once __DIR__ . '/bootstrap.php';\ninclude __DIR__ . '/partials/header.php';","example":"require_once __DIR__ . '/config/database.php';","points":["require прекращает выполнение при ошибке подключения; include выдаёт предупреждение.","_once предотвращает повторное подключение файла.","Строить путь удобно от __DIR__; не доверяй пользовательскому пути."],"tags":["PHP","include","require","require_once","подключение файлов"],"url":"https://www.php.net/manual/ru/function.include.php","search":true},{"lang":"php","id":"php-json","title":"PHP: JSON","summary":"Преобразуй массивы и объекты в JSON для обмена с браузером.","code":"$json = json_encode(\n    ['ok' => true, 'count' => 3],\n    JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR\n);","example":"$data = json_decode($body, true, 512, JSON_THROW_ON_ERROR);","points":["json_encode кодирует PHP-значение; json_decode разбирает JSON.","Обрабатывай ошибки кодирования и декодирования.","Для HTTP-ответа укажи Content-Type: application/json; charset=utf-8."],"tags":["PHP","JSON","json_encode","json_decode","API"],"url":"https://www.php.net/manual/ru/function.json-encode.php","search":true},{"lang":"php","id":"php-sessions","title":"PHP: сессии","summary":"Храни серверное состояние между запросами одного посетителя.","code":"session_start();\n$_SESSION['user_id'] = 42;","example":"session_start();\n$userId = $_SESSION['user_id'] ?? null;","points":["session_start вызывай до отправки HTML в ответе.","В сессии храни минимум данных, обычно идентификатор.","Для учётных данных настрой безопасные cookie и обновляй идентификатор после входа."],"tags":["PHP","session","сессия","$_SESSION","авторизация"],"url":"https://www.php.net/manual/ru/book.session.php","search":true},{"lang":"php","id":"php-passwords","title":"PHP: пароли и хеширование","summary":"Храни проверочные хеши паролей вместо исходных паролей.","code":"$hash = password_hash($password, PASSWORD_DEFAULT);\nif (password_verify($input, $hash)) {\n    echo 'Пароль подходит';\n}","example":"if (password_needs_rehash($hash, PASSWORD_DEFAULT)) {\n    $hash = password_hash($password, PASSWORD_DEFAULT);\n}","points":["Никогда не сохраняй и не журналируй исходный пароль.","password_hash автоматически управляет солью.","Используй password_verify для проверки."],"tags":["PHP","пароль","password_hash","password_verify","безопасность"],"url":"https://www.php.net/manual/ru/function.password-hash.php","search":true},{"lang":"php","id":"php-namespaces","title":"PHP: пространства имён","summary":"Избегай конфликтов имён в больших проектах.","code":"namespace App\\Service;\n\nclass Mailer\n{\n    public function send(): void {}\n}","example":"use App\\Service\\Mailer;\n$mailer = new Mailer();","points":["namespace указывается до обычного кода файла.","use создаёт короткое имя для класса, функции или константы.","Пространство имён отражает организацию кода, но не подключает сам файл."],"tags":["PHP","namespace","use","пространство имён","класс"],"url":"https://www.php.net/manual/ru/language.namespaces.php","search":true},{"lang":"php","id":"php-composer","title":"PHP: Composer и зависимости","summary":"Управляй библиотеками и автозагрузкой через Composer.","code":"composer require vendor/package","example":"{\n  \"autoload\": {\n    \"psr-4\": {\"App\\\\\": \"src/\"}\n  }\n}","points":["composer.json описывает зависимости и настройки проекта.","composer.lock фиксирует версии для воспроизводимой установки.","vendor/autoload.php подключает автозагрузку классов."],"tags":["PHP","Composer","composer.json","composer.lock","зависимости","автозагрузка"],"url":"https://www.php.net/manual/ru/language.oop5.autoload.php","search":true},{"lang":"php","id":"php-validation","title":"PHP: проверка данных на сервере","summary":"Проверяй типы, диапазоны и формат входящих данных на сервере.","code":"$email = filter_input(INPUT_POST, 'email', FILTER_VALIDATE_EMAIL);\nif ($email === false || $email === null) {\n    http_response_code(400);\n    exit('Проверь адрес почты');\n}","example":"$age = filter_input(INPUT_POST, 'age', FILTER_VALIDATE_INT, [\n    'options' => ['min_range' => 0, 'max_range' => 120],\n]);","points":["Проверка на клиенте не защищает сервер от поддельного запроса.","Валидируй по ожидаемому формату и бизнес-правилам.","Разделяй проверку значения и экранирование при выводе."],"tags":["PHP","валидация","filter_input","безопасность","проверка формы"],"url":"https://www.php.net/manual/ru/filter.filters.validation.php","search":true},{"lang":"php","id":"php-files","title":"PHP: чтение и запись файлов","summary":"Работай с файлами по явному пути и проверяй результат операции.","code":"$contents = file_get_contents(__DIR__ . '/data.txt');\nif ($contents === false) {\n    throw new RuntimeException('Не удалось прочитать файл');\n}","example":"file_put_contents(\n    __DIR__ . '/log.txt',\n    $message . PHP_EOL,\n    FILE_APPEND | LOCK_EX\n);","points":["Проверяй false при чтении и записи.","Не используй пользовательский ввод как путь без строгой проверки.","Для одновременной записи нескольких процессов применяй блокировку, если подходит задаче."],"tags":["PHP","файл","file_get_contents","file_put_contents","чтение","запись"],"url":"https://www.php.net/manual/ru/filesystem.file-access.php","search":true},{"lang":"php","id":"php-transactions","title":"PHP: транзакции базы данных","summary":"Объединяй несколько изменений базы в атомарную операцию.","code":"$pdo->beginTransaction();\ntry {\n    updateBalance($pdo, $from, -100);\n    updateBalance($pdo, $to, 100);\n    $pdo->commit();\n} catch (Throwable $error) {\n    $pdo->rollBack();\n    throw $error;\n}","example":"$pdo->beginTransaction();\n// изменить связанные записи\n$pdo->commit();","points":["Транзакция подтверждается commit или отменяется rollback.","Откатывай транзакцию при исключении.","Транзакция не заменяет подготовленные запросы и проверку бизнес-правил."],"tags":["PHP","PDO","транзакция","commit","rollback","база данных"],"url":"https://www.php.net/manual/ru/pdo.transactions.php","search":true}];
